<template><div class="finance-modal" @click.self="$emit('close')"><section class="finance-dialog" role="dialog" aria-modal="true" aria-label="Upload finance document"><header><h2>Upload financial document</h2><button @click="$emit('close')" aria-label="Close upload">×</button></header><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="save"><label>File (PDF, PNG, JPEG, TXT or CSV; up to 5 MB)<input type="file" accept="application/pdf,image/png,image/jpeg,text/plain,text/csv" required @change="file=$event.target.files[0]" /></label><label>Document type<select v-model="draft.kind"><option v-for="v in kinds" :key="v" :value="v">{{ label(v) }}</option></select></label><label v-if="role==='manager'">Visibility<select v-model="draft.visibility"><option value="organization">Shared with organization</option><option value="internal">Finance team only</option></select></label><label v-for="f in links" :key="f.key">{{ f.label }}<select v-model="draft[f.key]"><option value="">None</option><option v-for="row in data[f.source]||[]" :key="row.id" :value="row.id">{{ row.name||row.title }}</option></select></label><p>Uploads are preserved as separate evidence records. Existing documents are not overwritten.</p><button class="primary" :disabled="busy">{{ busy?'Uploading…':'Upload document' }}</button></form></section></div></template>
<script setup>
import {ref,onBeforeUnmount} from 'vue';import api from '../../services/api';import {label} from './financeForms';
const props=defineProps({agencyId:Number,role:String,data:Object,expenseId:Number,requestId:Number});const emit=defineEmits(['close','saved']);const file=ref(null),error=ref(''),busy=ref(false),draft=ref({kind:props.expenseId?'receipt':'report',visibility:'organization',expenseId:props.expenseId||'',programId:'',grantId:'',requestId:props.requestId||''});let active=true;onBeforeUnmount(()=>{active=false;});
const kinds=['receipt','invoice','award','grant_agreement','report','statement','contract','other'],links=[{key:'programId',label:'Program',source:'programs'},{key:'grantId',label:'Grant',source:'grants'},{key:'expenseId',label:'Expense request',source:'expenses'},{key:'requestId',label:'Reporting / support request',source:'requests'}];
async function save(){busy.value=true;error.value='';try{if(!file.value||file.value.size>5*1024*1024)throw Error('Choose a document up to 5 MB.');const form=new FormData();form.append('file',file.value);for(const [k,v] of Object.entries(draft.value))if(v)form.append(k,v);await api.post(`/finance-operations/${props.agencyId}/documents`,form,{headers:{'Content-Type':'multipart/form-data'}});if(active)emit('saved');}catch(e){if(active)error.value=e.response?.data?.error?.message||e.message||'Upload failed';}finally{if(active)busy.value=false;}}
</script>
